(5708165, 829987, 40490, '<td valign="top">Though the intent, I imagine, was a dark photograph, perhaps a trifle brighter wouldn''t have hurt</td>', 'Though the intent, I imagine, was a dark photograph, perhaps a trifle brighter wouldn''t have hurt', '2009-11-01 07:15:59.000000', NULL, 1),
