(5715721, 828895, 72670, '<td valign="top">Nice score! Blue looks good on you (and your page). Much better than bright green.<a href="//www.dpchallenge.com/image.php?IMAGE_ID=827454" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/70000-74999/72670/120/Copyrighted_Image_Reuse_Prohibited_827454.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/70000-74999/72670/120/Copyrighted_Image_Reuse_Prohibited_827454.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/70000-74999/72670/120/Copyrighted_Image_Reuse_Prohibited_827454.jpg"/></a><br/><br/><i>Message edited by author 2009-11-05 19:29:28.</i></td>', 'Nice score! Blue looks good on you (and your page). Much better than bright green.', '2009-11-05 19:28:23.000000', '2009-11-05 19:29:28.000000', 0),
